=========== core/FU_ALU.v ===========
`timescale 1ns / 1ps

module FU_ALU(
    input clk, EN,
    input[3:0] ALUControl,
    input[31:0] ALUA, ALUB,
    output[31:0] res,
    output zero, overflow,
    output finish
);

    reg state;
    assign finish = state == 1'b1;
    initial begin
        state = 0;
    end

    // TODO: implement — stateful ALU functional unit
    // On EN & ~state: latch inputs (ALUA, ALUB, ALUControl) and set state to 1
    // On state == 1: reset state to 0
    // Must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    // zero should be 1 when res is all zeros.
    // overflow should be set for signed ADD/SUB overflow.
    assign res = 32'b0;
    assign zero = 1'b0;
    assign overflow = 1'b0;

endmodule=========== core/FU_div.v ===========
`timescale 1ns / 1ps

module FU_div(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    wire res_valid;
    wire[63:0] divres;

    reg state;
    assign finish = res_valid & state;
    initial begin
        state = 0;
    end

    // TODO: implement — division functional unit
    // On EN & ~state: latch inputs (A, B), set A_valid and B_valid to 1, set state to 1.
    // When res_valid: clear A_valid, B_valid, state to 0.
    // Otherwise: clear A_valid, B_valid but keep state.
    // Instantiate divider IP with AXI-style valid/data interface.
    // Result is the quotient from divres[63:32].
    assign res = 32'b0;

endmodule=========== core/FU_jump.v ===========
`timescale 1ns / 1ps

module FU_jump(
	input clk, EN, JALR,
	input[3:0] cmp_ctrl,
	input[31:0] rs1_data, rs2_data, imm, PC,
	output[31:0] PC_jump, PC_wb,
	output is_jump, finish
);

	wire cmp_res;
    reg state;
    assign finish = state == 1'b1;
	initial begin
        state = 0;
    end

	// TODO: implement — jump/branch functional unit
	// On EN & ~state: latch inputs (JALR, cmp_ctrl, rs1_data, rs2_data, imm, PC)
	// and set state to 1. On state==1: reset state to 0.
	// Use cmp_32 to compare rs1_data_reg and rs2_data_reg.
	// Compute PC_jump = (JALR ? rs1_data_reg : PC_reg) + imm_reg.
	// Compute PC_wb = PC_reg + 4.
	// is_jump = cmp_ctrl_reg[0] | cmp_res (unconditional or condition met).
	assign is_jump = 1'b0;
	assign PC_jump = 32'b0;
	assign PC_wb = 32'b0;

endmodule=========== core/FU_mem.v ===========
`timescale 1ns / 1ps

module FU_mem(
    input clk, EN, mem_w,
    input[2:0] bhw,
    input[31:0] rs1_data, rs2_data, imm,
    output[31:0] mem_data,
    output finish
);

    reg[1:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // TODO: implement — memory functional unit
    // On EN & ~|state: latch inputs (mem_w, bhw, rs1_data, rs2_data, imm) and
    // set state to 2'b10. State shifts right each cycle (2'b10 -> 2'b01 -> 2'b00).
    // finish when state[0] == 1.
    // Compute address = rs1_data_reg + imm_reg using add_32.
    // Instantiate RAM_B with computed address.
    assign mem_data = 32'b0;

